bool doReq(beginner_tutorials::sum::Request& req, beginner_tutorials::sum::Response& resp){
int num1 = req.num1;
int num2 = req.num2;
ROS_INFO("服务器接收到的请求数据为:num1 = %d, num2 = %d",num1, num2);
if (num1 < 0 || num2 < 0)
{
ROS_ERROR("提交的数据异常：数据不可以为负数");
return false;
}
resp.sum = num1 + num2;
return true;
}
